  static String text(BuildContext context, String key) {
    final locale = Localizations.localeOf(context);
    var code = locale.languageCode;
    if (code == 'zh') {
      final script = locale.scriptCode?.toLowerCase();
      final country = locale.countryCode?.toUpperCase();
      if (script == 'hant' || country == 'TW' || country == 'HK' || country == 'MO') {
        code = 'zh_Hant';
      }
    }
    return _v[code]?[key] ?? _service[code]?[key] ?? _v['en']?[key] ?? _service['en']?[key] ?? key;
  }

  static String canonicalLocale(String localeTag) {
    final normalized = localeTag.replaceAll('-', '_');
    final lower = normalized.toLowerCase();
    if (lower.startsWith('zh_hant') ||
        lower.startsWith('zh_tw') ||
        lower.startsWith('zh_hk') ||
        lower.startsWith('zh_mo')) {
      return 'zh_Hant';
    }
    final language = lower.split('_').first;
    return _v.containsKey(language) || _service.containsKey(language)
        ? language
        : 'en';
  }

  static String textForLocale(String localeTag, String key) {
    final code = canonicalLocale(localeTag);
    return _v[code]?[key] ??
        _service[code]?[key] ??
        _v['en']?[key] ??
        _service['en']?[key] ??
        key;
  }

  static String format(
    BuildContext context,
    String key,
    Map<String, Object?> values,
  ) {
    var value = text(context, key);
    for (final item in values.entries) {
      value = value.replaceAll('{'+item.key+'}', item.value?.toString() ?? '');
    }
    return value;
  }
}
